public class SaveToolConfigDialogTest : AbstractGhidraHeadedIntegrationTest {

	private PluginTool tool;
	private TestEnv env;
	private SaveToolConfigDialog saveDialog;
	private JTextField toolNameField;
	private JList<object> iconList;
